import java.util.*;

public final class PlayerActivity extends Activity {
    DataStore data;JSONObject item;LibVLC vlc;MediaPlayer player;VLCVideoLayout video;MediaProxy proxy;ParcelFileDescriptor file;
    FrameLayout root;LinearLayout controls,top,bottom;SeekBar timeline;TextView clock,message;Button pause,skip;Handler handler=new Handler(Looper.getMainLooper());
    String viewing="";double resume=0,lastPosition=0,duration=0;long lastSave=0,lastSeek=0;boolean done=false,ended=false,dragging=false,introHandled=false,fill=false,destroyed=false,tracksReady=false,manualHidden=false;int resumeTries=0,nextSeconds=-1;
    final Runnable hide=()->{if(player!=null&&player.isPlaying()&&!dragging&&nextSeconds<0)controls.setVisibility(View.GONE);};
    final Runnable tick=new Runnable(){public void run(){if(destroyed)return;update();handler.postDelayed(this,500);}};
    @Override public void onCreate(Bundle b){super.onCreate(b);data=NoirApp.data;item=data.item(getIntent().getStringExtra("id"));if(item==null){finish();return;}
        getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE);
        getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);
        JSONObject bookmark=item.optJSONObject("progress");boolean restart=getIntent().getBooleanExtra("restart",false);resume=!restart&&bookmark!=null&&!bookmark.optBoolean("completed")?bookmark.optDouble("position",0):0;lastPosition=resume;duration=bookmark==null?item.optDouble("duration",0):bookmark.optDouble("duration",0);
        viewing=!restart&&bookmark!=null&&!bookmark.optBoolean("completed")&&!bookmark.optString("viewingId").isEmpty()?bookmark.optString("viewingId"):UUID.randomUUID().toString();
        if(b!=null){viewing=b.getString("viewing",viewing);lastPosition=b.getDouble("position",lastPosition);resume=lastPosition;done=b.getBoolean("done");}
        build();try{ArrayList<String> opts=new ArrayList<>(Arrays.asList("--no-video-title-show","--vout=android_display","--aout=android_audiotrack","--android-display-chroma=RV32","--sub-language=eng,en","--freetype-rel-fontsize=16","--quiet"));vlc=new LibVLC(this,opts);player=new MediaPlayer(vlc);player.attachViews(video,null,true,true);player.setVideoScale(MediaPlayer.ScaleType.SURFACE_BEST_FIT);player.setEventListener(e->handler.post(()->{if(destroyed)return;if(e.type==MediaPlayer.Event.EndReached)end();else if(e.type==MediaPlayer.Event.EncounteredError){save();message.setText("Couldn't play this video. Check that the PC is connected, or link a phone copy.");show();}else if(e.type==MediaPlayer.Event.Playing){data.consumeVideo(item.optString("id"));message.setText("");show();}}));
            Media media;String local=data.localFile(item.optString("id"));if(!local.isEmpty()){file=local.startsWith("file:")?ParcelFileDescriptor.open(new java.io.File(Uri.parse(local).getPath()),ParcelFileDescriptor.MODE_READ_ONLY):getContentResolver().openFileDescriptor(Uri.parse(local),"r");if(file==null)throw new java.io.IOException("Phone file is unavailable");media=new Media(vlc,file.getFileDescriptor());}else {proxy=new MediaProxy(data,item.optString("id"));media=new Media(vlc,Uri.parse(proxy.url()));media.addOption(":network-caching=1200");}media.setHWDecoderEnabled(true,false);player.setMedia(media);media.release();player.play();handler.post(tick);
        }catch(Exception e){message.setText("Couldn't open video. "+e.getMessage());}}
    int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
    TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(MainActivity.WHITE);return t;}
    Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setTextSize(12);b.setAllCaps(false);b.setTextColor(MainActivity.WHITE);b.setBackground(MainActivity.bg(MainActivity.PANEL,dp(10)));b.setPadding(dp(10),0,dp(10),0);b.setOnClickListener(v->{action.run();show();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(46));p.setMargins(dp(4),0,dp(4),0);b.setLayoutParams(p);return b;}
    void build(){root=new FrameLayout(this);root.setBackgroundColor(Color.BLACK);setContentView(root);video=new VLCVideoLayout(this);root.addView(video,new FrameLayout.LayoutParams(-1,-1));View touch=new View(this);root.addView(touch,new FrameLayout.LayoutParams(-1,-1));touch.setOnClickListener(v->{if(controls.getVisibility()==View.VISIBLE){manualHidden=true;controls.setVisibility(View.GONE);handler.removeCallbacks(hide);}else{manualHidden=false;show();}});
        controls=new LinearLayout(this);controls.setOrientation(LinearLayout.VERTICAL);controls.setFitsSystemWindows(true);root.addView(controls,new FrameLayout.LayoutParams(-1,-1));top=new LinearLayout(this);top.setPadding(dp(8),dp(14),dp(12),dp(14));top.setGravity(Gravity.CENTER_VERTICAL);top.setBackgroundColor(Color.argb(220,12,12,14));top.addView(button("‹ Library",this::finish));TextView title=text(item.optString("title")+" · "+MainActivity.episode(item),16);title.setSingleLine();title.setEllipsize(android.text.TextUtils.TruncateAt.END);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));top.addView(button("Audio",()->tracks(false)));top.addView(button("Subtitles",()->tracks(true)));top.addView(button("Fit",()->{fill=!fill;player.setVideoScale(fill?MediaPlayer.ScaleType.SURFACE_FIT_SCREEN:MediaPlayer.ScaleType.SURFACE_BEST_FIT);}));controls.addView(top);
        message=text("Opening video…",14);message.setTextColor(MainActivity.GOLD);message.setGravity(Gravity.CENTER);message.setClickable(false);controls.addView(message,new LinearLayout.LayoutParams(-1,0,1));bottom=new LinearLayout(this);bottom.setOrientation(LinearLayout.VERTICAL);bottom.setBackgroundColor(Color.argb(220,12,12,14));bottom.setPadding(dp(12),dp(8),dp(12),dp(16));timeline=new SeekBar(this);timeline.setMax(100000);timeline.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){dragging=true;handler.removeCallbacks(hide);}public void onProgressChanged(SeekBar s,int n,boolean user){if(user)clock.setText(DataStore.time(duration*n/100000)+" / "+DataStore.time(duration));}public void onStopTrackingTouch(SeekBar s){dragging=false;seek(duration*s.getProgress()/100000);}});bottom.addView(timeline);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);pause=button("Pause",()->{if(player.isPlaying()){player.pause();save();}else player.play();});row.addView(pause);row.addView(button("−10s",()->seek(lastPosition-10)));row.addView(button("+10s",()->seek(lastPosition+10)));clock=text("0:00",12);clock.setGravity(Gravity.CENTER);row.addView(clock,new LinearLayout.LayoutParams(0,-2,1));skip=button("Skip intro",()->{JSONObject intro=item.optJSONObject("intro");if(intro!=null)seek(intro.optDouble("end"));});skip.setVisibility(View.GONE);row.addView(skip);row.addView(button("Next",this::next));bottom.addView(row);controls.addView(bottom);}
    void show(){if(manualHidden)return;controls.setVisibility(View.VISIBLE);handler.removeCallbacks(hide);handler.postDelayed(hide,3000);}
    void update(){if(player==null)return;long time=player.getTime(),length=player.getLength();if(length>0)duration=length/1000d;if(time>=0&&!ended)lastPosition=time/1000d;
        if(resume>0&&player.isSeekable()&&resumeTries++<20){if(Math.abs(lastPosition-resume)<2){lastPosition=resume;resume=0;}else {player.setTime((long)(resume*1000),false);lastPosition=resume;}}
        if(!tracksReady&&player.isPlaying()&&player.getSpuTracksCount()>0){tracksReady=true;for(MediaPlayer.TrackDescription t:player.getSpuTracks()){String name=t.name.toLowerCase(Locale.ROOT);if(t.id>=0&&(name.contains("english")||name.contains("eng"))){player.setSpuTrack(t.id);break;}}}
        if(!dragging){timeline.setProgress((int)(100000*lastPosition/Math.max(1,duration)));clock.setText(DataStore.time(lastPosition)+" / "+DataStore.time(duration));}pause.setText(player.isPlaying()?"Pause":"Play");
        JSONObject intro=item.optJSONObject("intro");boolean inside=intro!=null&&lastPosition>=intro.optDouble("start")&&lastPosition<intro.optDouble("end");skip.setVisibility(inside?View.VISIBLE:View.GONE);if(inside&&!introHandled&&player.isPlaying()&&data.settings().optBoolean("autoSkipIntro",true)){introHandled=true;seek(intro.optDouble("end"));}
        double threshold=duration;JSONObject outro=item.optJSONObject("outro");if(data.settings().optBoolean("markWatchedAtCredits",true)&&duration>=300){threshold=duration-Math.min(duration*.05,item.optBoolean("movie")?180:90);if(outro!=null&&outro.optDouble("start")>=duration*.5&&outro.optDouble("start")<duration)threshold=outro.optDouble("start");}
        if(!done&&resume==0&&duration>0&&lastPosition>=threshold&&player.isPlaying()&&!dragging&&System.currentTimeMillis()-lastSeek>1500){done=true;save();}
        if(System.currentTimeMillis()-lastSave>=2000&&resume==0&&player.isPlaying())save();}
    void seek(double seconds){if(player==null)return;introHandled=true;resume=0;lastSeek=System.currentTimeMillis();lastPosition=Math.max(0,Math.min(Math.max(0,duration-.3),seconds));if(ended){ended=false;player.stop();player.play();resume=lastPosition;resumeTries=0;}else player.setTime((long)(lastPosition*1000),false);save();show();}
    void save(){if(item==null||viewing.isEmpty())return;if(resume>0&&!ended)lastPosition=resume;data.progress(item.optString("id"),viewing,lastPosition,duration,done);lastSave=System.currentTimeMillis();data.syncSoon();}
    void end(){if(ended)return;ended=true;done=true;manualHidden=false;if(duration>0)lastPosition=duration;save();show();if(data.settings().optBoolean("autoNext",true)&&nextItem()!=null){nextSeconds=8;handler.removeCallbacks(hide);countdown();}else message.setText("Finished · saved to history");}
    void countdown(){if(destroyed||nextSeconds<0)return;if(nextSeconds==0){nextSeconds=-1;next();return;}message.setText("Next episode in "+nextSeconds+"s · tap here to cancel");message.setOnClickListener(v->{nextSeconds=-1;message.setText("Autoplay cancelled");});nextSeconds--;handler.postDelayed(this::countdown,1000);}
    JSONObject nextItem(){JSONArray q=data.playQueue();for(int n=0;n<q.length();n++){JSONObject queued=data.item(q.optString(n));if(queued!=null&&!queued.optString("id").equals(item.optString("id"))&&(!data.localFile(queued.optString("id")).isEmpty()||data.online&&queued.optBoolean("available")))return queued;}if(item.optBoolean("movie"))return null;List<JSONObject> all=DataStore.objects(data.items());all.sort(Comparator.comparingInt((JSONObject i)->i.optInt("season")).thenComparingInt(i->i.optInt("episode")));int s=item.optInt("season"),e=item.optInt("episode");for(JSONObject i:all)if(i.optString("group").equals(item.optString("group"))&&(s==0?i.optInt("season")==0:i.optInt("season")>0)&&(i.optInt("season")>s||i.optInt("season")==s&&i.optInt("episode")>e)&&!MainActivity.completed(i)&&(!data.localFile(i.optString("id")).isEmpty()||data.online&&i.optBoolean("available")))return i;return null;}
    void next(){JSONObject n=nextItem();if(n==null){message.setText("No next episode available");return;}save();startActivity(new Intent(this,PlayerActivity.class).putExtra("id",n.optString("id")));finish();}
    void tracks(boolean subs){if(player==null)return;handler.removeCallbacks(hide);MediaPlayer.TrackDescription[] tracks=subs?player.getSpuTracks():player.getAudioTracks();if(tracks==null||tracks.length==0){message.setText("No tracks available yet");return;}String[] labels=new String[tracks.length];int selected=-1;for(int n=0;n<tracks.length;n++){labels[n]=tracks[n].name;if(tracks[n].id==(subs?player.getSpuTrack():player.getAudioTrack()))selected=n;}new AlertDialog.Builder(this).setTitle(subs?"Subtitles":"Audio").setSingleChoiceItems(labels,selected,(d,n)->{if(subs)player.setSpuTrack(tracks[n].id);else player.setAudioTrack(tracks[n].id);d.dismiss();show();}).setNegativeButton("Close",(d,w)->show()).show();}
    @Override protected void onSaveInstanceState(Bundle b){save();b.putString("viewing",viewing);b.putDouble("position",lastPosition);b.putBoolean("done",done);super.onSaveInstanceState(b);}
    @Override protected void onPause(){if(player!=null&&player.isPlaying())player.pause();save();handler.removeCallbacks(hide);super.onPause();}
    @Override protected void onDestroy(){destroyed=true;handler.removeCallbacksAndMessages(null);if(player!=null){player.setEventListener(null);player.stop();player.detachViews();player.release();}if(vlc!=null)vlc.release();if(proxy!=null)proxy.close();if(file!=null)try{file.close();}catch(Exception ignored){}super.onDestroy();}
}
